(()=>{
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const mouse={x:-9999,y:-9999};

  /* ---------- certificates (add a base64 or image link in `img` to show the picture) ---------- */
  const CERTS=[
    {name:'Big Data Computing',issuer:'NPTEL',meta:'Elite · 61% · IIT Kanpur · 2025',img:'data:image/jpeg;base64,'},
    {name:'Programming in Python',issuer:'Meta',meta:'Coursera · 2025',img:'data:image/jpeg;base64,'},
    {name:'Advanced Java Development',issuer:'KGISL',meta:'Coursera · 2026',img:'data:image/jpeg;base64,'},
    {name:'C Programming with DSA Foundation',issuer:'KGISL',meta:'Coursera · 2025',img:'data:image/jpeg;base64,'}
  ];
  $('#certs').innerHTML=CERTS.map(c=>`
    <article class="card cert" data-tilt>
      <div class="shot">${c.img?`<img src="${c.img}" alt="${c.name} certificate">`:`<div class="ph"><b>${c.issuer}</b><small>Certificate</small></div>`}</div>
      <div><h3>${c.name}</h3><p>${c.meta}</p></div>
    </article>`).join('');
  const lb=$('#lb'),lbi=$('img',lb);
  document.addEventListener('click',e=>{
    const im=e.target.closest('.cert .shot img, .resume-img');
    if(im){lbi.src=im.src;lb.hidden=false;return}
    if(!lb.hidden&&e.target.closest('#lb'))lb.hidden=true;
  });
  addEventListener('keydown',e=>{if(e.key==='Escape')lb.hidden=true});

  /* ---------- typed role line ---------- */
  const roles=['Computer Science Student','Frontend Developer','UI/UX Designer'];
  const typed=$('#typed');
  if(!reduce){
    let r=0,i=roles[0].length,del=true;
    const tick=()=>{
      const w=roles[r];
      if(del){i--;if(i<=0){del=false;r=(r+1)%roles.length;i=0}}
      else{i++;if(i>=roles[r].length)del=true}
      typed.textContent=roles[r].slice(0,i)||' ';
      setTimeout(tick,del?(i===roles[r].length?1600:35):70);
    };
    setTimeout(tick,1800);
  }

  /* ---------- particle field + ripples ---------- */
  const cv=$('#bg'),cx=cv.getContext('2d');
  let W=0,H=0,P=[],ripples=[];
  function size(){
    const d=Math.min(devicePixelRatio||1,2);
    W=innerWidth;H=innerHeight;cv.width=W*d;cv.height=H*d;cx.setTransform(d,0,0,d,0,0);
    const n=Math.round(Math.min(90,W*H/15000));
    P=Array.from({length:n},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.35,r:Math.random()*1.5+.7}));
    if(reduce)draw();
  }
  function draw(){
    cx.clearRect(0,0,W,H);
    for(const p of P){
      if(!reduce){
        const dx=p.x-mouse.x,dy=p.y-mouse.y,d=Math.hypot(dx,dy);
        if(d<150&&d>0){const f=(1-d/150)*2.2;p.x+=dx/d*f;p.y+=dy/d*f}
        p.x+=p.vx;p.y+=p.vy;
        if(p.x<-10)p.x=W+10;else if(p.x>W+10)p.x=-10;
        if(p.y<-10)p.y=H+10;else if(p.y>H+10)p.y=-10;
      }
      cx.fillStyle='rgba(244,236,238,.4)';
      cx.beginPath();cx.arc(p.x,p.y,p.r,0,6.283);cx.fill();
    }
    cx.lineWidth=1;
    for(let i=0;i<P.length;i++){
      const a=P[i];
      for(let j=i+1;j<P.length;j++){
        const b=P[j],d=Math.hypot(a.x-b.x,a.y-b.y);
        if(d<110){cx.strokeStyle=`rgba(125,17,40,${(1-d/110)*.22})`;cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(b.x,b.y);cx.stroke()}
      }
      const m=Math.hypot(a.x-mouse.x,a.y-mouse.y);
      if(m<170){cx.strokeStyle=`rgba(190,45,75,${(1-m/170)*.5})`;cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(mouse.x,mouse.y);cx.stroke()}
    }
    for(let k=ripples.length-1;k>=0;k--){
      const r=ripples[k];r.r+=3.2;r.a-=.018;
      if(r.a<=0){ripples.splice(k,1);continue}
      cx.strokeStyle=`rgba(190,45,75,${r.a})`;cx.lineWidth=2;
      cx.beginPath();cx.arc(r.x,r.y,r.r,0,6.283);cx.stroke();
    }
  }
  function loop(){draw();requestAnimationFrame(loop)}
  addEventListener('resize',size);size();
  if(!reduce)requestAnimationFrame(loop);

  /* ---------- cursor glow (eased) ---------- */
  const glow=$('#glow');let gx=innerWidth/2,gy=innerHeight/3;
  if(!reduce){
    (function g(){gx+=(mouse.x-gx)*.12;gy+=(mouse.y-gy)*.12;if(mouse.x>-999)glow.style.transform=`translate(${gx}px,${gy}px)`;requestAnimationFrame(g)})();
  }

  /* ---------- pointer: bubble tilt, card spotlight/tilt, magnetic buttons ---------- */
  const mags=$$('.mag');
  addEventListener('pointermove',e=>{
    mouse.x=e.clientX;mouse.y=e.clientY;
    if(reduce)return;
    for(const m of mags){
      const b=m.getBoundingClientRect(),cxm=b.left+b.width/2,cym=b.top+b.height/2;
      const dx=e.clientX-cxm,dy=e.clientY-cym;
      m.style.transform=Math.hypot(dx,dy)<b.width/2+60?`translate(${dx*.28}px,${dy*.28}px)`:'';
    }
  },{passive:true});
  document.addEventListener('pointerleave',()=>{mouse.x=mouse.y=-9999;mags.forEach(m=>m.style.transform='')});
  $$('[data-tilt]').forEach(c=>{
    c.addEventListener('pointermove',e=>{
      const b=c.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;
      c.style.setProperty('--mx',x+'px');c.style.setProperty('--my',y+'px');
      if(!reduce)c.style.transform=`perspective(800px) rotateX(${(.5-y/b.height)*6}deg) rotateY(${(x/b.width-.5)*6}deg) translateY(-3px)`;
    });
    c.addEventListener('pointerleave',()=>{c.style.transform=''});
  });

  /* ---------- click ripple ---------- */
  addEventListener('pointerdown',e=>{if(!reduce)ripples.push({x:e.clientX,y:e.clientY,r:4,a:.8})});

  /* ---------- copy buttons ---------- */
  $$('.copy').forEach(b=>b.addEventListener('click',()=>{
    const done=()=>{const t=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=t,1400)};
    const fb=()=>{const v=b.parentElement.querySelector('.v'),r=document.createRange();r.selectNodeContents(v);const s=getSelection();s.removeAllRanges();s.addRange(r);try{document.execCommand('copy')}catch(_){}done()};
    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(b.dataset.copy).then(done,fb);else fb();
  }));

  /* ---------- nav highlight ---------- */
  const links=$$('#nav a');
  const io=new IntersectionObserver(es=>es.forEach(en=>{
    if(en.isIntersecting)links.forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+en.target.id));
  }),{rootMargin:'-40% 0px -55% 0px'});
  $$('header[id],section[id]').forEach(s=>io.observe(s));
})();

/* ---------- resume download ---------- */
document.getElementById('dl').addEventListener('click',function(e){e.preventDefault();var b=atob(""),a=new Uint8Array(b.length);for(var i=0;i<b.length;i++)a[i]=b.charCodeAt(i);var u=URL.createObjectURL(new Blob([a],{type:'application/pdf'})),l=document.createElement('a');l.href=u;l.download='Sanjana_S_Resume.pdf';l.click();});
